3	
4	describe("MHPCO Claim Office — base premiums and component blocks", () => {
5	  // Base premiums for main items (price list)
6	  it("single sword → 100 G base premium", () => {
7	    expect(basePremium([{ type: "sword" }])).toBe(100);
8	  });
9	  it("single amulet → 60 G base premium", () => {
10	    expect(basePremium([{ type: "amulet" }])).toBe(60);
11	  });
12	  it("single staff → 80 G base premium", () => {
13	    expect(basePremium([{ type: "staff" }])).toBe(80);
14	  });
15	  it("single potion → 40 G base premium", () => {
16	    expect(basePremium([{ type: "potion" }])).toBe(40);
17	  });
18	  it("single component (rune) → 25 G base premium", () => {
19	    expect(basePremium([{ type: "rune" }])).toBe(25);
20	  });
21	
22	  // Building block of 3 alike components
23	  it("2 runes → 50 G base premium (no block)", () => {
24	    expect(basePremium([{ type: "rune" }, { type: "rune" }])).toBe(50);
25	  });
26	  it("3 runes → 60 G base premium (block applies)", () => {
27	    expect(basePremium([{ type: "rune" }, { type: "rune" }, { type: "rune" }])).toBe(60);
28	  });
29	  it("4 runes → 100 G base premium (no block — block requires exactly 3)", () => {
30	    expect(
31	      basePremium([{ type: "rune" }, { type: "rune" }, { type: "rune" }, { type: "rune" }]),
32	    ).toBe(100);
33	  });
34	  it("7 runes → 175 G base premium", () => {
35	    expect(basePremium(Array(7).fill({ type: "rune" }))).toBe(175);
36	  });
37	
38	  // "Alike" components — ❓ resolved: alike means exactly the same type
39	  it.todo("2 runes + 1 moonstone → 75 G base premium (no block: different types)");
40	  it.todo("3 runes + 3 moonstones → 120 G base premium (two separate blocks)");
41	});
