56	  // Modifier scope on multi-item policies — ❓ resolved
57	  it.todo("cursed sword + plain amulet (0 years, first contract) → curse surcharge is 50% of the cursed item's base only");
58	
59	  // Modifier thresholds
60	  it.todo("customer with exactly 2 years → loyalty discount applies");
61	  it.todo("customer with 1 year → no loyalty discount");
62	  it.todo("sword with exactly enchantment 5 → high-enchantment surcharge applies");
63	  it.todo("sword with enchantment 5 and cursed → both surcharges apply");
64	  it.todo("sword with enchantment 4 (not cursed) → no high-enchantment or curse surcharge");
